INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17301, 'Isaiah 38:22', 'Isaiah', 38, 22, '&nbsp;او حزقياه تپوس کړے وو، ”کومه نښه به دا ثابته کړى چې زۀ به بيا د مالِک خُدائ کور ته لاړ شم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17302, 'Isaiah 39:1', 'Isaiah', 39, 1, '&nbsp;تقريباً هم په هغه وخت د بابل بادشاه د بلدان زوئ مرودک‌بلدان خبر شو چې حزقياه بادشاه بيمار وو او اوس روغ شوے دے، نو مرودک‌بلدان ورله يو خط او يوه تُحفه ولېږله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17303, 'Isaiah 39:2', 'Isaiah', 39, 2, '&nbsp;حزقياه پېغام وړونکو ته په خېر راغلے ووئيل او هغوئ ته يې خپل سپين زر، سرۀ زر، خپلې مصالحې او قيمتى تېل او ټول فوجى سامان او وسله وښودل. د هغۀ د ګودام په کوټو کښې يا د هغۀ د بادشاهۍ په بل ځائ کښې هم داسې څۀ پاتې نۀ شول چې هغۀ ورته ښودلى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17304, 'Isaiah 39:3', 'Isaiah', 39, 3, '&nbsp;بيا يشعياه پېغمبر حزقياه بادشاه له لاړو او تپوس يې ترې نه وکړو چې، ”دا سړى د کوم ځائ نه راغلى دى او هغوئ تا ته څۀ ووئيل؟“ حزقياه ورته وفرمائيل، ”هغوئ د يو لرې مُلک، بابل نه راغلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17305, 'Isaiah 39:4', 'Isaiah', 39, 4, '&nbsp;هغۀ ورته وفرمائيل، ”هغوئ په محل کښې څۀ وليدل؟“ حزقياه ورته وفرمائيل چې، ”هغوئ هر څۀ وليدل. د ګودام په کوټو کښې داسې څۀ نشته چې ما ورته ښودلى نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17306, 'Isaiah 39:5', 'Isaiah', 39, 5, '&nbsp;بيا يشعياه بادشاه ته وفرمائيل، ”مالِک خُدائ ربُ الافواج داسې فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17307, 'Isaiah 39:6', 'Isaiah', 39, 6, '&nbsp;يو داسې وخت راروان دے چې ستا په محل کښې هر يو څيز، چې ستا پلار نيکۀ تر ننه پورې جمع کړى دى، نو هغه به بابل ته يوړے شى. هيڅ به هم پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17308, 'Isaiah 39:7', 'Isaiah', 39, 7, '&nbsp;ستا د خپل اولاد نه به څۀ بوتلے شى او هغوئ به د دې دپاره خصيان کړے شى چې د بابل بادشاه په محل کښې خِدمت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17309, 'Isaiah 39:8', 'Isaiah', 39, 8, '&nbsp;نو حزقياه بادشاه د دې په مطلب پوهه شو چې د هغۀ په ټول ژوند کښې به امن او سلامتيا وى، نو هغۀ ورته وفرمائيل، ”تا چې ما له د مالِک خُدائ نه کوم پېغام راوړے دے هغه ښۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17310, 'Isaiah 40:1', 'Isaiah', 40, 1, '&nbsp;خُدائ پاک فرمائى، ”زما خلقو له تسلى ورکړئ، زما خلقو له تسلى ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17311, 'Isaiah 40:2', 'Isaiah', 40, 2, '&nbsp;د يروشلم خلقو سره ډيرې په نرمه ژبه خبرې کوئ. او هغوئ ته ووايئ چې ستاسو د خفګان ورځې ختمې شوې او اوس ستاسو ګناهونه معاف شوى دى. ځکه چې د مالِک خُدائ د لاسه هغوئ ته د خپلو ګناهونو يو په دوه سزا مِلاو شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17312, 'Isaiah 40:3', 'Isaiah', 40, 3, '&nbsp;په بيابان کښې د نعرې وهونکى آواز دے، ”د مالِک خُدائ دپاره په بيابان کښې لار جوړه کړئ. په صحرا کښې هغۀ ته لارې نېغې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17313, 'Isaiah 40:4', 'Isaiah', 40, 4, '&nbsp;هره دره به ډکه شى، هره غونډۍ او غر به هوار شى. کاږۀ به نېغ کړے شى، او ناهمواره به هواره کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17314, 'Isaiah 40:5', 'Isaiah', 40, 5, '&nbsp;نو د مالِک خُدائ جلال به راڅرګند شى، او ټول بنى آدم به هغه په شريکه وګورى. مالِک خُدائ په خپله دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17315, 'Isaiah 40:6', 'Isaiah', 40, 6, '&nbsp;يو آواز ووئيل، ”چغه ووهه.“ نو ما تپوس وکړو، ”زۀ څۀ چغه ووهم؟“ دا چې بنى آدم د واښو په شان دى، او د هغوئ ښائست د ځنګلى ګل په شان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17316, 'Isaiah 40:7', 'Isaiah', 40, 7, '&nbsp;کله چې د مالِک خُدائ هوا وچليږى نو واښۀ اوچ شى او ګلونه مړاوى شى، نو داسې دا د خلقو دپاره هم ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17317, 'Isaiah 40:8', 'Isaiah', 40, 8, '&nbsp;نو، واښۀ اوچ شى او ګلونه مړاوى شى، خو د مالِک خُدائ کلام د همېشه دپاره قائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17318, 'Isaiah 40:9', 'Isaiah', 40, 9, '&nbsp;اے صيونه، يو اوچت غر ته وخېژه او اعلان وکړه. اے يروشلمه، د اوچت آواز سره چغه ووهه، او يرېږئ مۀ. د يهوداه ښاريې ته ووايئ چې، ”ستاسو خُدائ پاک دا دے راروان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17319, 'Isaiah 40:10', 'Isaiah', 40, 10, '&nbsp;ګورئ، مالِک خُدائ تعالىٰ لوئ قدرت سره راروان دے، هغه به د طاقت سره حکومت وکړى، د هغۀ اجر د هغۀ سره دے او د هغۀ انعام د هغۀ نه مخکښې مخکښې روان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17320, 'Isaiah 40:11', 'Isaiah', 40, 11, '&nbsp;هغه به د يو شپون په شان د خپلو ګډو ساتنه کوى، هغه به ګډُورى په خپل غېږ کښې وړى او زړۀ سره به يې نزدې نيولى وى او ګډې به يې ډېر په خيال سره ځان سره روانې کړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17321, 'Isaiah 40:12', 'Isaiah', 40, 12, '&nbsp;سمندر څوک په موټى کښې نيولے شى، يا څوک آسمان د لاسونو په ذريعه ناپ کولے شى؟ د زمکې د خاورې وزن چا معلوم کړے دے يا څوک په تله غرونه او د غرونو غونډۍ تللے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17322, 'Isaiah 40:13', 'Isaiah', 40, 13, '&nbsp;مالِک خُدائ ته څوک ښودلے شى چې داسې کوه؟ هغۀ ته څوک ښودنه کولے شى يا مشوره ورکولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17323, 'Isaiah 40:14', 'Isaiah', 40, 14, '&nbsp;ولې مالِک خُدائ ته د چا د مشورې ضرورت وى څۀ؟ چې ورته پوهه ورکړى او د صحيح کارونو طريقه ورته وښائى؟ يا کله چا هغۀ ته عِلم ورکړے دے چې د ښۀ عِلم تېرولو چل ورته وښائى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17324, 'Isaiah 40:15', 'Isaiah', 40, 15, '&nbsp;نه، يقيناً چې قومونه د مالِک خُدائ دپاره هيڅ هم نۀ دى، په بالټى کښې د اوبو د يو څاڅکى يا په تله کښې د دوړې نه زيات نۀ دى، هغه ټوله دُنيا داسې اوچتوى لکه چې د شګې يوه دانه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17325, 'Isaiah 40:16', 'Isaiah', 40, 16, '&nbsp;د لبنان په ځنګلو کښې ټول ځناور خُدائ پاک ته د قربانى کېدو دپاره لږ دى، او د دې ځنګلونو ونې د سوزېدونکو نذرانو د اور بلولو دپاره ډېرې کمې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17326, 'Isaiah 40:17', 'Isaiah', 40, 17, '&nbsp;د هغۀ په وړاندې ټول قومونه هيڅ هم نۀ دى، د هغۀ په نظر کښې هغوئ نشت دى، هيڅ څيز هم نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17327, 'Isaiah 40:18', 'Isaiah', 40, 18, '&nbsp;د خُدائ پاک مثال د چا سره ورکولے شى؟ تۀ به څنګه ووائې چې د هغۀ صورت څنګه دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17328, 'Isaiah 40:19', 'Isaiah', 40, 19, '&nbsp;کاريګر خو اول بُت جوړ کړى، بيا زرګر په هغې باندې سرۀ زر وخېژوى او د سپينو زرو په زنځيرونو باندې يې ښائسته کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17329, 'Isaiah 40:20', 'Isaiah', 40, 20, '&nbsp;کوم سړے چې سرۀ زر يا سپين زر نۀ شى اخستلے هغه به داسې لرګى خوښوى چې نۀ ورَستيږى. هغه يو ماهِر کاريګر لټوى چې يو داسې بُت جوړ کړى چې نۀ غورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17330, 'Isaiah 40:21', 'Isaiah', 40, 21, '&nbsp;تا ته پته نشته څۀ؟ تا نۀ دى اورېدلى څۀ؟ تا ته د شروع نه نۀ وُو وئيلے شوى څۀ؟ د دُنيا د شروع نه واخله تر اوسه پورې تۀ پوهه نۀ شوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17331, 'Isaiah 40:22', 'Isaiah', 40, 22, '&nbsp;خُدائ پاک د زمکې نه بره په خپل تخت ناست دے، او هلته نه خلق لکه د مُلخانو په شان ښکارى. هغۀ آسمان د پردى په شان خور کړے دے، د هغه خېمې په شان چې د اوسېدو دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17332, 'Isaiah 40:23', 'Isaiah', 40, 23, '&nbsp;هغه طاقتور حکمرانان راټيټوى او په نشت باندې يې بدلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17333, 'Isaiah 40:24', 'Isaiah', 40, 24, '&nbsp;هغوئ د وړو بوټو په شان دى، چې اوس اوس راشنۀ شوى وى او لږې لږې جرړې يې کړې وى. کله چې مالِک خُدائ هوا راولېږى، نو دا اوچې شى او د خسڼى په شان والوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17334, 'Isaiah 40:25', 'Isaiah', 40, 25, '&nbsp;د هغه مقدس ذات مثال د چا سره ورکولے شى؟ د هغۀ په شان بل څوک شته؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17335, 'Isaiah 40:26', 'Isaiah', 40, 26, '&nbsp;آسمان ته وګوره. تا له چې په نظر کوم ستورى راځى دا چا پېدا کړى دى؟ دا هغه ذات دے چې دا يې د لښکر په شان روان کړى دى، هغۀ ته پته ده چې دا ستورى څومره دى او هر يو ته خپل خپل نوم اخلى. د هغۀ قوت دومره زيات دے، چې د دې نه يو هم نۀ دے کم شوے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17336, 'Isaiah 40:27', 'Isaiah', 40, 27, '&nbsp;نو اے بنى اِسرائيلو، تاسو شکايت ولې کوئ چې مالِک خُدائ ستاسو په تکليفونو باندې خبر نۀ دے يا چې ستاسو سره بې‌اِنصافى کيږى نو تاسو وايئ چې هغه ستاسو خيال نۀ ساتى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17337, 'Isaiah 40:28', 'Isaiah', 40, 28, '&nbsp;تاسو ته پته نشته څۀ؟ تاسو اورېدلى نۀ دى؟ چې مالِک خُدائ د همېشه دپاره خُدائ پاک دے، هغۀ ټوله دُنيا پېدا کړې ده. هغه هيڅکله نۀ ستړے کيږى او نۀ ستومانه کيږى. او د هغۀ د حکمت خاتمه نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17338, 'Isaiah 40:29', 'Isaiah', 40, 29, '&nbsp;هغه کمزورو او ستړو له طاقت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17339, 'Isaiah 40:30', 'Isaiah', 40, 30, '&nbsp;نو ځوانان هم ستړى ستومانه شى، او خراب راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17340, 'Isaiah 40:31', 'Isaiah', 40, 31, '&nbsp;خو چې څوک په مالِک خُدائ باندې يقين ساتى نو هغوئ ته به يو نوے طاقت مِلاو شى. هغوئ به داسې اوچت الوځى لکه چې د باز وزر ورته لګېدلى وى، هغوئ به منډه وهى او نۀ به ستړى کيږى، هغوئ به پېدل ګرځى او نۀ به ستومانه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17341, 'Isaiah 41:1', 'Isaiah', 41, 1, '&nbsp;اے د لرې مُلکونو خلقو، خاموشۍ سره ما ته غوږ ونيسئ. تيار شئ چې په عدالت کښې خپله مقدمه پېش کړئ، تاسو ته به د خبرو کولو موقع مِلاو شى. راځئ چې په يو ځائ دا فېصله وکړُو چې څوک په حقه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17342, 'Isaiah 41:2', 'Isaiah', 41, 2, '&nbsp;هغه څوک وو چا چې فتح کوونکے د نمرخاتۀ نه راوستلو، او چې چرته هم تلو نو هغۀ له به يې فتح ورکوله؟ هغۀ له به په قومونو او بادشاهانو چا فتح ورکوله؟ د هغۀ تُورې به هغوئ داسې وهل لکه چې خاوره وى. د هغۀ غشو به هغوئ د بوسو په شان خوارۀ وارۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17343, 'Isaiah 41:3', 'Isaiah', 41, 3, '&nbsp;هغه ورپسې دے او ښۀ په خېر سره روان دے، دومره تېز دے چې پښې يې په زمکه پوره نۀ لګيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17344, 'Isaiah 41:4', 'Isaiah', 41, 4, '&nbsp;هغه څوک دے چې داسې يې وکړل؟ څوک دے چې د شروع پيړۍ په پيړۍ آوازونه کوى؟ زۀ، مالِک خُدائ د ابتدا نه موجود يم، او په انتها کښې به هم موجود يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17345, 'Isaiah 41:5', 'Isaiah', 41, 5, '&nbsp;د لرې مُلکونو خلقو دا ليدلى دى او يرېدلې دى، د دُنيا لرې علاقې لړزيږى. او هغوئ يو بل ته راجخت شى او رانزدې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17346, 'Isaiah 41:6', 'Isaiah', 41, 6, '&nbsp;هغوئ د يو بل مدد کوى او يو بل ته وائى چې، ”حوصله وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17347, 'Isaiah 41:7', 'Isaiah', 41, 7, '&nbsp;ترکاڼ د زرګر حوصله افزائى کوى، او څوک چې بُت په ټکولو باندې هواروى د هغه سړى حوصله افزائى کوى څوک چې دا په مېخونو يو ځائ کوى او وائى، ”اوس ټيک دے.“ او بيا دا بُت هغوئ په مېخونو باندې مضبوطوى چې ونۀ غورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17348, 'Isaiah 41:8', 'Isaiah', 41, 8, '&nbsp;خو اے زما خِدمتګاره، بنى اِسرائيله، زما د دوست اِبراهيم اولاده. تاسو هغه خلق يئ چې ما غوره کړى يئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17349, 'Isaiah 41:9', 'Isaiah', 41, 9, '&nbsp;تاسو ما د دُنيا د سرونو نه راوستلئ، ما تاسو د دې لرې ګوټونو نه راوغوښتلئ او ما تاسو ته وفرمائيل، ”تاسو زما خِدمت کوونکى يئ. ما تاسو غوره کړئ او رد مې نۀ کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17350, 'Isaiah 41:10', 'Isaiah', 41, 10, '&nbsp;يرېږئ مۀ، زۀ ستاسو مل يم. زۀ ستاسو خُدائ پاک يم، د څۀ نه هم مۀ وارخطا کېږئ. زۀ به تاسو مضبوط کړم او طاقت به درکړم، زۀ به په خپل زورَور ښى لاس سره ستاسو حِفاظت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17351, 'Isaiah 41:11', 'Isaiah', 41, 11, '&nbsp;څوک چې تاسو ته غصه وى نو د شکست د شرم سره به مخ شى. څوک چې درسره جنګ کوى نو هغوئ به نيست و نابود شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17352, 'Isaiah 41:12', 'Isaiah', 41, 12, '&nbsp;تاسو به هغه ظالمان دشمنان لټوئ، خو پېدا به يې نۀ کړئ ځکه چې هغوئ به د زمکې د مخ نه ورک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17353, 'Isaiah 41:13', 'Isaiah', 41, 13, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم، زۀ تاسو تکړه کوم او درته وايم چې، ”مۀ يرېږئ، زۀ به ستاسو مدد کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17354, 'Isaiah 41:14', 'Isaiah', 41, 14, '&nbsp;مالِک خُدائ فرمائى، ”اے بنى اِسرائيلو، تاسو واړۀ او کمزورى يئ، خو يرېږئ مه، زۀ به ستاسو مدد کوم. زۀ د بنى اِسرائيلو مقدس ذات يم، زۀ هغه هستى يم څوک چې تاسو بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17355, 'Isaiah 41:15', 'Isaiah', 41, 15, '&nbsp;ګورئ، زۀ به تاسو د درمند د تختې په شان جوړ کړم، چې غاښونه يې تېرۀ وى. تاسو به غرونه ذرې ذرې کوئ او تباه کوئ به يې، د غرونو غونډۍ به لکه د بوسو په شان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17356, 'Isaiah 41:16', 'Isaiah', 41, 16, '&nbsp;تاسو به دا هوا ته وُلئ، باد به دا اخوا وړى، او طوفان به يې خوارۀ وارۀ کوى. نو بيا به تاسو خوشحاله يئ ځکه چې زۀ ستاسو مالِک خُدائ يم، تاسو به زما ثناء صِفت کوئ، ځکه چې زۀ د بنى اِسرائيلو مقدس ذات يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17357, 'Isaiah 41:17', 'Isaiah', 41, 17, '&nbsp;کله چې غريبانان او ضرورتمند اوبۀ لټوى، خو مومى يې نه، او د هغوئ مرۍ د تندې نه اوچې شى، نو بيا به زۀ، مالِک خُدائ د هغوئ سوال قبول کړم، زۀ، د بنى اِسرائيلو خُدائ پاک به هغوئ هيڅکله پرې نۀ ږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17358, 'Isaiah 41:18', 'Isaiah', 41, 18, '&nbsp;زۀ به د خُشکو غرونو په مينځ کښې سيندونه روان کړم او په واديانو کښې به د اوبو چينې روانې کړم. زۀ به صحرا د اوبو په تالابونو بدله کړم او اوچه زمکه به په بهېدونکو چينو بدله کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17359, 'Isaiah 41:19', 'Isaiah', 41, 19, '&nbsp;زۀ به په صحرا کښې د دِيار ونې راشنې کړم، او د کيکر، د سر درو ونې او د زيتُونو ونې به راشنې کړم. په خُشک مُلک کښې به ځنګل راوټوکيږى، د نخترو، د صُندل د ونو او د سبر ونو ځنګل به راوټوکيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17360, 'Isaiah 41:20', 'Isaiah', 41, 20, '&nbsp;زۀ به دا د دې دپاره کوم چې خلق دا وګورى او پوهه شى، چې هغوئ پرې غور وکړى او پته ورته ولګى چې د مالِک خُدائ قوت دا کړى دى. او د بنى اِسرائيلو مقدس ذات دا پېدا کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17361, 'Isaiah 41:21', 'Isaiah', 41, 21, '&nbsp;مالِک خُدائ فرمائى، ”تاسو د خپلو معبودانو په حق کښې معامله وړاندې کړئ.“ د اِسرائيل بادشاه فرمائى، ”خپل ښۀ دليلونه پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17362, 'Isaiah 41:22', 'Isaiah', 41, 22, '&nbsp;راشئ او پېشګوئې ورکړئ چې څۀ به کيږى، نو چې پته راته ولګى کله به داسې وشى. عدالت ته د تېرې زمانې واقعاتو وضاحت وکړئ، او مونږ ته ووايئ چې د دې څۀ مطلب دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17363, 'Isaiah 41:23', 'Isaiah', 41, 23, '&nbsp;مونږ ته ووايئ چې په راتلونکى وخت کښې به څۀ کيږى، نو بيا به مونږ ته پته ولګى چې تاسو خدايان يئ. څۀ نه څۀ خو وکړئ کنه کۀ هغه ښۀ وى او کۀ بد، چې مونږ ګبراؤ شُو او ويريږو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17364, 'Isaiah 41:24', 'Isaiah', 41, 24, '&nbsp;خو تاسو هيڅ هم نۀ يئ او ستاسو کار هم فضول دے، څوک چې تاسو غوره کړى هغوئ د نفرت قابل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17365, 'Isaiah 41:25', 'Isaiah', 41, 25, '&nbsp;ما يو سړے د شمال طرف نه راپارولے دے نو هغه راروان دے، هغه زما د نوم درناوے کوى او هغه د نمرخاتۀ طرف نه راروان دے. هغه به په حکمرانانو داسې ګرځى لکه چې په خټو ګرځى داسې لکه چې کُلال په خټه پښې ږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17366, 'Isaiah 41:26', 'Isaiah', 41, 26, '&nbsp;د شروع نه چا دا اعلان وکړو نو چې مونږ ته به پته وے؟ د اول نه چا د دې پېشګوئې وکړه چې مونږ ووايو چې هغه صحيح دے؟ هيچا هم د دې اعلان او پېشګوئې نۀ ده کړې. هيچا هم ستا يوه خبره هم نۀ ده اورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17367, 'Isaiah 41:27', 'Isaiah', 41, 27, '&nbsp;اول ما صيون ته د دې اعلان وکړو، او ما يروشلم ته د خوشخبرۍ پېغام وړُونکى ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17368, 'Isaiah 41:28', 'Isaiah', 41, 28, '&nbsp;خو ما په معبودانو کښې داسې يو هم ونۀ ليدلو چې ما له مشوره راکړى، او په دوئ کښې يو هم نشته چې زما د سوال جواب راکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17369, 'Isaiah 41:29', 'Isaiah', 41, 29, '&nbsp;ګورئ، دا ټول معبودان بې‌کاره دى، هغوئ هيڅ هم نۀ شى کولے، دا بُتان هسې تش کدوان دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17370, 'Isaiah 42:1', 'Isaiah', 42, 1, '&nbsp;دا زما خادِم دے چا ته چې ما طاقت ورکړے دے او څوک چې ما غوره کړے دے، زما محبوب چې روح مې پرې خوشحاله دے. ما خپل روح په هغۀ سورے کړے دے، او هغه به غېرو قومونو ته اِنصاف رسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17371, 'Isaiah 42:2', 'Isaiah', 42, 2, '&nbsp;هغه به نۀ جنګ کوى، نۀ شور، او نۀ به په کوڅو کښې د هغۀ آواز اورېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17372, 'Isaiah 42:3', 'Isaiah', 42, 3, '&nbsp;هغه به يوه کږه لوخه هم نۀ ماتوى او نۀ به کمه بلېدونکې ډيوه مړه کوى. هغه به په وفادارۍ سره اِنصاف قائم ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17373, 'Isaiah 42:4', 'Isaiah', 42, 4, '&nbsp;هغه به نۀ بې‌حوصلې کيږى او نۀ به نااُميده کيږى، هغه به په زمکه اِنصاف قائم کړى. لرې لرې مُلکونه به د هغۀ د تعليماتو په انتظار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17374, 'Isaiah 42:5', 'Isaiah', 42, 5, '&nbsp;خُدائ پاک آسمانونه پېدا کړل او خوارۀ يې کړل، هغۀ زمکه او چې په دې کښې هر څۀ اوسيږى هغه يې پېدا کړل، هغۀ د زمکې ټولو خلقو له ساه او ژوند ورکړو. او اوس خُدائ پاک خپل خِدمت کوونکى ته وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17375, 'Isaiah 42:6', 'Isaiah', 42, 6, '&nbsp;”ما، مالِک خُدائ صداقت سره راوغوښتې، زۀ به تا د لاس نه ونيسم او محفوظ به دې ساتم. ستا په ذريعه به زۀ د ټولو خلقو سره يو لوظ وکړم، او ستا په ذريعه به زۀ قومونو له رڼا راوړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17376, 'Isaiah 42:7', 'Isaiah', 42, 7, '&nbsp;تۀ به د ړندو سترګې وغړوې او هغه خلق به آزاد کړې چې کوم د قېدخانې په تيارۀ کښې پراتۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17377, 'Isaiah 42:8', 'Isaiah', 42, 8, '&nbsp;زۀ مالِک خُدائ يم. او هم دا زما نوم دے. زۀ به خپل جلال بل هيچا ته نۀ ورکوم، او زما په ثناء صِفت کښې به بُتانو ته هيڅ برخه نۀ ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17378, 'Isaiah 42:9', 'Isaiah', 42, 9, '&nbsp;ما چې د کومو خبرو پېشګوئې کړې وه هغه رښتيا شوې دى. او اوس زۀ تاسو ته د نوؤ واقعو اعلان کوم. اوس به زۀ تاسو ته نوى څيزونه وښايم چې دا لا شوى هم نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17379, 'Isaiah 42:10', 'Isaiah', 42, 10, '&nbsp;مالِک خُدائ ته يو نوے حمد ووايئ، اے ټولې دُنيا، د هغۀ ثناء صِفت بيان کړئ. اے په سمندر کښې مسافرانو او د سمندر ټول مخلوقه، د هغۀ ثناء صِفت کوئ. اے لرې مُلکونو او په هغې کښې اوسېدونکو خلقو، د هغۀ حمد ووايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17380, 'Isaiah 42:11', 'Isaiah', 42, 11, '&nbsp;صحرا او د دې ښارونه دې د خُدائ پاک ثناء صِفت کوى، د قيدار د کلو خلق دې د هغۀ ثناء صِفت کوى. او څوک چې د سلع په ښار کښې اوسيږى هغوئ دې د غرونو د سرونو نه د خوشحالۍ چغې ووهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17381, 'Isaiah 42:12', 'Isaiah', 42, 12, '&nbsp;کوم خلق چې په لرې مُلکونو کښې اوسيږى هغوئ دې د مالِک خُدائ ثناء صِفت او جلال بيان کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17382, 'Isaiah 42:13', 'Isaiah', 42, 13, '&nbsp;مالِک خُدائ د يو جنګيالى په شان جنګ له ځى، هغه به لکه د فوجى په شان جذبه کښې راشى او د جنګ نعرې به وهى او د خپلو دشمنانو خِلاف به خپل طاقت ښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17383, 'Isaiah 42:14', 'Isaiah', 42, 14, '&nbsp;خُدائ پاک فرمائى، ”زۀ د ډېر وخت نه خاموش وم، زۀ د ډېر وخت نه چپ وم نو غږ مې نۀ کولو. خو اوس زۀ د داسې ښځې په شان يم چې فرياد کوى او چغې وهى لکه چې ماشوم يې پېدا کيږى او ساه ساه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17384, 'Isaiah 42:15', 'Isaiah', 42, 15, '&nbsp;زۀ به غرونه او د غرونو غونډۍ تباه کړم او واښۀ او ونې به اوچې کړم. زۀ به د سيندونو نه اوچې زمکې جوړې کړم او د اوبو تالابونه به يې اوچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17385, 'Isaiah 42:16', 'Isaiah', 42, 16, '&nbsp;زۀ به خپل ړاندۀ خلق روان کړم په هغه لار به يې بوځم چې هغوئ پرې هيڅکله سفر نۀ وى کړے. زۀ به د هغوئ وړاندې تيارۀ په رڼا بدله کړم او د هغوئ مخې ته هغه کندې کَپرې زمکه به هواره کړم. دا زما وعدې دى، او دا وعدې به زۀ پوره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17386, 'Isaiah 42:17', 'Isaiah', 42, 17, '&nbsp;خو هر څوک چې په بُتانو ايمان لرى، او ورته وائى چې تاسو زمونږ خُدايان يئ، نو هغوئ به سخت وشرميږى او رد به کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17387, 'Isaiah 42:18', 'Isaiah', 42, 18, '&nbsp;اے کڼو خلقو، واورئ. اے ړندو خلقو، ښۀ وګورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17388, 'Isaiah 42:19', 'Isaiah', 42, 19, '&nbsp;زما د خِدمت کوونکى په شان ړوند څوک دے؟ زما د پېغمبر په شان کُوڼ څوک دے څوک چې زۀ درلېږم؟ اګر چې ما هغۀ سره لوظ کړے دے خو بيا هم د مالِک خُدائ د خادِم په شان ړوند څوک نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17389, 'Isaiah 42:20', 'Isaiah', 42, 20, '&nbsp;اګر چې تاسو ډېر څۀ ليدلى دى، خو تاسو څۀ توجو نۀ ده ورکړې، اګر چې ستاسو غوږونه خبره واورى، خو تاسو يې نه اورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17390, 'Isaiah 42:21', 'Isaiah', 42, 21, '&nbsp;مالِک خُدائ د خپل صداقت د خاطره خوشحاله وو، چې خپل شريعت لوئ کړى او جلال ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17391, 'Isaiah 42:22', 'Isaiah', 42, 22, '&nbsp;خو اوس د هغۀ خلق لوټ کړے شوى او شوکېدلى دى، هغوئ ټول په کندو کښې ګېر کړے شوى دى او په قېدخانو کښې اچولے شوى دى. هغوئ نه د لوټ مال جوړ شوے دے، خو د هغوئ بچ کولو له هيڅ څوک هم رانۀ غلل. هغوئ نيولے شوى دى خو هيچا هم ونۀ وئيل چې، ”دوئ واپس کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17392, 'Isaiah 42:23', 'Isaiah', 42, 23, '&nbsp;په تاسو کښې به څوک دې ته غوږ ونيسى؟ د راتلونکى وخت دپاره به څوک دې ته پام وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17393, 'Isaiah 42:24', 'Isaiah', 42, 24, '&nbsp;اِسرائيليان لوټ مارانو او ډاکوانو ته چا حواله کړل؟ ولې دا مالِک خُدائ ونۀ کړل، د چا خِلاف چې مونږ ګناه کړې ده؟ هغوئ د هغۀ په لاره باندې تلو نه اِنکار وکړو، هغوئ د هغۀ د شريعت نافرمانى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17394, 'Isaiah 42:25', 'Isaiah', 42, 25, '&nbsp;نو په دې وجه هغۀ هغوئ ته د خپلې غصې زور وښودلو او د جنګ سختى يې ورباندې راوسته. د هغۀ غصه په ټول اِسرائيل کښې د اور په شان بلېده، خو هغوئ ته هيڅ پته نۀ لګېده چې څۀ کيږى، دا د هغوئ خلاف بلېده خو هغوئ ترېنه هيڅ سبق وانۀ خستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17395, 'Isaiah 43:1', 'Isaiah', 43, 1, '&nbsp;اے بنى اِسرائيلو، هغه مالِک خُدائ چا چې تاسو پېدا کړى يئ هغه فرمائى چې، ”يرېږئ مه، ځکه چې ما تاسو په بيعه اخستى يئ. ما تاسو ته په نوم آواز کړے دے، تاسو زما يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17396, 'Isaiah 43:2', 'Isaiah', 43, 2, '&nbsp;کله چې تاسو د سمندر په ژورو اوبو کښې روان يئ، نو زۀ به ستاسو مل يم، کله چې تاسو د سمندرونو نه تېرېږئ نو ډوبېږئ به نه. کله چې تاسو په اور کښې تېرېږئ، نو تاسو به نۀ سوزئ، او د اور شُغلې به تاسو ته نقصان نۀ درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17397, 'Isaiah 43:3', 'Isaiah', 43, 3, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم، زۀ د بنى اِسرائيلو هغه مقدس ذات يم، چې ستاسو خلاصونکے يم. ستاسو د آزادولو دپاره زۀ مِصر ورکوم، ستا په ځائ زۀ ايتهوپيا او سِيبا ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17398, 'Isaiah 43:4', 'Isaiah', 43, 4, '&nbsp;زما په نظر کښې تاسو قيمتى او عزتمند يئ، او تاسو په ما ګران يئ. نو په دې وجه به زۀ ستاسو په ځائ خلق ورکړم او ستاسو د ژوند په بدله کښې به زۀ قومونه ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17399, 'Isaiah 43:5', 'Isaiah', 43, 5, '&nbsp;يرېږئ مه، زۀ ستاسو مل يم. زۀ به تاسو او ستاسو خلق د نمرخاتۀ طرف نه او د نمرپرېواتۀ طرف نه راغونډ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17400, 'Isaiah 43:6', 'Isaiah', 43, 6, '&nbsp;زۀ به شمال ته ووايم چې هغوئ پرېږده چې لاړ شى او جنوب ته به ووايم چې هغوئ مۀ ايساروه. زما زامن د لرې مُلکونو نه واپس راوله، زما لوڼه د زمکې د هر سر نه واپس راوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');